INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist DHCP nur dafür da, IPs statisch zu vergeben?', 2, '[{"text": "Nein", "correct": true, "because": "DHCP vergibt dynamisch"}, {"text": "Ja", "correct": false, "because": "Statisch ist manuell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe übernimmt DHCP in einem Netzwerk?', 3, '[{"text": "IP-Adressen zuweisen", "correct": true, "because": "Automatisiert Konfiguration"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Sicherheit nicht Ziel"}, {"text": "Traffic filtern", "correct": false, "because": "Firewall-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen liefert DHCP an Clients?', 5, '[{"text": "IP-Adresse", "correct": true, "because": "Grundfunktion"}, {"text": "Subnetzmaske", "correct": true, "because": "Netzwerkkonfiguration"}, {"text": "Passwort", "correct": false, "because": "Sicherheit nicht enthalten"}, {"text": "MAC-Adresse", "correct": false, "because": "Client-seitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DHCP vereinfacht IP-Management. b) Es blockiert Angriffe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit nicht Aufgabe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der DHCP-Konfiguration?', 4, '[{"text": "IP-Bereich", "correct": false, "because": "Definiert Adresspool"}, {"text": "Lease-Zeit", "correct": false, "because": "Bestimmt Vergabedauer"}, {"text": "Router-Farbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DHCP auch ohne Server läuft?', 2, '[{"text": "Nein", "correct": true, "because": "Server oder Router nötig"}, {"text": "Ja", "correct": false, "because": "Kein Peer-to-Peer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll nutzt DHCP für die Kommunikation?', 3, '[{"text": "UDP", "correct": true, "because": "Ports 67 und 68"}, {"text": "TCP", "correct": false, "because": "Zuverlässigkeit nicht nötig"}, {"text": "HTTP", "correct": false, "because": "Web-Protokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind für DHCP essenziell?', 5, '[{"text": "DHCP-Server", "correct": true, "because": "Vergibt Adressen"}, {"text": "Client", "correct": true, "because": "Fragt Adressen an"}, {"text": "Firewall", "correct": false, "because": "Optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DHCP reduziert Konflikte. b) Es sichert Daten. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Datenabsicherung nicht Ziel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DHCP?', 4, '[{"text": "IP-Pool", "correct": false, "because": "Grundlage der Vergabe"}, {"text": "Gateway-Adresse", "correct": false, "because": "Wichtig für Routing"}, {"text": "Manuelle IP-Einträge", "correct": true, "because": "DHCP automatisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DHCP immer aktiv?', 2, '[{"text": "Nein", "correct": true, "because": "Kann deaktiviert werden"}, {"text": "Ja", "correct": false, "because": "Optional einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten kann DHCP zusätzlich liefern?', 4, '[{"text": "DNS-Server", "correct": true, "because": "Für Namensauflösung"}, {"text": "Gateway", "correct": true, "because": "Für Netzwerkzugriff"}, {"text": "Benutzername", "correct": false, "because": "Nicht Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DHCP IPs dauerhaft vergibt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Lease-Zeit begrenzt"}, {"text": "Ja", "correct": false, "because": "Dynamisch, nicht statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der DHCP-Einrichtung?', 3, '[{"text": "Adressbereich", "correct": true, "because": "Definiert verfügbare IPs"}, {"text": "Manuelle Zuweisung", "correct": false, "because": "Widerspricht DHCP"}, {"text": "Optisches Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DHCP nutzt Broadcast. b) Es ersetzt DNS.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DNS ist separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet DHCP?', 5, '[{"text": "Einfache Verwaltung", "correct": true, "because": "Automatisiert IPs"}, {"text": "Weniger Konflikte", "correct": true, "because": "Zentrale Vergabe"}, {"text": "Höhere Sicherheit", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DHCP unwichtig?', 3, '[{"text": "Lease-Zeit", "correct": false, "because": "Steuert Vergabe"}, {"text": "IP-Bereich", "correct": false, "because": "Definiert Pool"}, {"text": "Monitorauflösung", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann DHCP in kleinen Netzen ausgeschaltet werden?', 3, '[{"text": "Ja", "correct": true, "because": "Manuelle IPs möglich"}, {"text": "Nein", "correct": false, "because": "Optional nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DHCP auch statische IPs unterstützt?', 2, '[{"text": "Ja", "correct": true, "because": "Via Reservierungen"}, {"text": "Nein", "correct": false, "because": "Statisch konfigurierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature macht DHCP effizient?', 4, '[{"text": "Dynamische Vergabe", "correct": true, "because": "Automatisiert Prozesse"}, {"text": "Permanente IPs", "correct": false, "because": "Lease-basiert"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Netzwerkfaktor"}]');
